// Detailed analysis is one landscape workspace; only the explicit Apply writes.
var teamShapeMode='plan',teamShapeFrame=null,teamShapeMeasureCanvas=null;
function teamShapeBoard(d,tactic){
 const v=TeamShape.read(season,{tactic,mode:teamShapeMode,owner:tacticsDiagramOwner,zone:tacticsDiagramZone,positions:typeof customPositions==='undefined'?{}:customPositions});
 if(!v.valid){if(teamShapeMode==='current'){teamShapeMode='plan';return teamShapeBoard(d,tactic);}return '';}
 const shape=f=>f.split('').join('-'),point=p=>[10+(100-p.y)*3.6,10+p.x*2.1],control=(attr,items,value,disabled=false)=>Object.entries(items).map(([id,label])=>'<button type="button" data-'+attr+'="'+id+'" aria-pressed="'+(id===value)+'" '+(disabled?'disabled':'')+'>'+label+'</button>').join('');
 const colors={press:'#ffb580','press-screen':'#ffb580',intercept:'#ffb580',support:'#d1f68d',overlap:'#d1f68d',run:'#b6dcff',outlet:'#b6dcff'},dots=people=>people.map(p=>{const [x,y]=point(p),name=p.name.split(' ').at(-1).slice(0,7),fill=p.team===0?'#dd4c5d':'#d4dbe8',edge=p.team===0?colors[p.role]||'#fff':'#263c49';return '<g data-shape-player="'+escapeText(p.id)+'"><title>'+escapeText(p.name+' · '+p.roleLabel+' · 체력 '+p.energy)+'</title><circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="7" fill="'+fill+'" stroke="'+edge+'" stroke-width="2"/><text x="'+x.toFixed(1)+'" y="'+(y+2.5).toFixed(1)+'" font-size="7" text-anchor="middle" fill="'+(p.team===0?'#fff':'#14242c')+'">'+p.no+'</text></g>';}).join('');
 teamShapeFrame=v;const select=(attribute,items,value)=>'<select data-shape-filter="'+attribute+'" aria-label="'+(attribute==='owner'?'공 소유':'전개 위치')+'" '+(v.mode==='current'?'disabled':'')+'>'+Object.entries(items).map(([id,label])=>'<option value="'+id+'" '+(id===value?'selected':'')+'>'+label+'</option>').join('')+'</select>';const [bx,by]=point(v.ball),metrics=[['폭','width','m'],['깊이','depth','m'],['압박 담당','pressure','명'],['공격 지원','support','명'],['공 뒤 인원','behind','명'],['침투·출구','runs','명']],labels={balanced:'균형 운영',press:'전방 압박',counter:'빠른 역습',lowBlock:'로우 블록'},decision=v.decision?'<p class="shape-decision"><b>현재 판단 예시</b> '+escapeText(v.decision.actor)+' · '+escapeText({carry:'공 운반',pass:'패스',cross:'크로스',shot:'슈팅'}[v.decision.kind]||v.decision.kind)+(v.decision.receiver?' → '+escapeText(v.decision.receiver):'')+'</p>':'',current=d.context.tactic===tactic;
 return '<section class="team-shape-board" aria-label="실제 엔진 전술 분석"><aside class="shape-orders"><h3>지시 비교</h3><div class="shape-tactics" role="group" aria-label="전술 미리보기">'+control('tactics-preview',labels,tactic)+'</div><p class="shape-fitness">체력 평균 <b>'+Math.round(d.condition.averageEnergy)+'</b> · 최저 <b>'+Math.round(d.condition.minimumEnergy)+'</b></p><button type="button" class="shape-apply" data-tactics-apply="'+tactic+'" '+(current?'disabled':'')+'>'+(current?'현재 경기 지시':'이 지시 적용')+'</button><p class="shape-apply-note">미리보기 후 적용 · 닫아도 경기 정지</p></aside><section class="shape-field"><div class="shape-scenario" role="group" aria-label="공 소유와 전개 위치">'+'<div class="shape-scenario-buttons">'+control('tactics-owner',TeamShape.owners,v.owner,v.mode==='current')+control('tactics-zone',TeamShape.zones,v.zone,v.mode==='current')+'</div><div class="shape-scenario-filters">'+select('owner',TeamShape.owners,v.owner)+select('zone',TeamShape.zones,v.zone)+'</div></div><figure><svg viewBox="0 0 380 230" role="img" aria-label="'+escapeText(v.observation+' · '+(v.mode==='plan'?'지시 목표 배치':'현재 실제 위치'))+'"><rect x="1" y="1" width="378" height="228" rx="6" fill="#1a4235"/><g stroke="#a7c6b4" stroke-opacity=".38" fill="none"><rect x="10" y="10" width="360" height="210"/><path d="M190 10V220M10 66H66V164H10M370 66H314V164H370"/><circle cx="190" cy="115" r="31"/></g>'+dots(v.opponent)+dots(v.own)+'<g class="shape-names"></g><circle cx="'+bx.toFixed(1)+'" cy="'+by.toFixed(1)+'" r="4" fill="white" stroke="#14242c" stroke-width="1.5"/></svg><figcaption><b>'+escapeText(v.observation)+'</b> · 우리 '+shape(v.formations.own)+' → '+escapeText(v.opponentClub.short)+' '+shape(v.formations.opponent)+'</figcaption></figure><p class="shape-legend"><span>● 압박</span><span>● 지원</span><span>● 침투</span> · 나머지는 대형·커버</p></section><aside class="shape-report"><div class="shape-mode" role="group" aria-label="대형 표시 기준">'+control('shape-mode',{plan:'지시 대형'},v.mode)+control('shape-mode',{current:'현재 위치'},v.mode,!v.canCurrent)+'</div><table><caption>'+(v.mode==='plan'?'목표 배치 비교':'실제 위치·선택 지시')+'</caption><thead><tr><th>항목</th><th>우리</th><th>상대</th></tr></thead><tbody>'+metrics.map(([name,key,unit])=>'<tr><th'+(key==='behind'?' title="골키퍼를 뺀, 공과 자기 골문 사이의 필드 선수 수"':'')+'>'+name+'</th><td>'+v.metrics[0][key]+unit+'</td><td>'+v.metrics[1][key]+unit+'</td></tr>').join('')+'</tbody></table>'+decision+'<p class="shape-evidence">'+escapeText(v.note)+'</p></aside></section>';
}
document.getElementById('tactics-board').addEventListener('click',event=>{const button=event.target.closest('[data-shape-mode]');if(!button||button.disabled)return;const d=readTacticsPlan();if(!d.valid)return;teamShapeMode=button.dataset.shapeMode;const host=$('tactics-board');host.innerHTML=tacticsBoardMarkup(d,tacticsPreview||d.context.tactic);queueTeamShapeFit();host.querySelector('[data-shape-mode="'+teamShapeMode+'"]')?.focus({preventScroll:true});});

function queueTeamShapeFit(){requestAnimationFrame(fitTeamShape);}
function fitTeamShape(){
 const svg=document.querySelector('#tactics-board .shape-field svg'),frame=teamShapeFrame;if(!svg||!svg.checkVisibility()||!frame)return;
 const rect=svg.getBoundingClientRect(),scale=Math.min(rect.width/380,rect.height/230);if(scale<=0)return;
 const adapt=rows=>rows.map(p=>({...p,x:(10+(100-p.y)*3.6)/380*100,y:(10+p.x*2.1)/230*100})),value={own:adapt(frame.own),opponent:adapt(frame.opponent)},canvas=teamShapeMeasureCanvas||(teamShapeMeasureCanvas=document.createElement('canvas')),ctx=canvas.getContext('2d'),host=svg.querySelector('.shape-names');
 let font=7.5,labels=[];const overlaps=rows=>rows.some((p,i)=>rows.slice(i+1).some(q=>Math.min(p.x+p.width,q.x+q.width)-Math.max(p.x,q.x)>.1&&Math.min(p.y+p.height,q.y+q.height)-Math.max(p.y,q.y)>.1));
 for(let attempt=0;attempt<4;attempt++){font=7.5-attempt*.5;ctx.font=font+'px system-ui';labels=Movement.nameLabels(value,380*scale,230*scale,name=>ctx.measureText(name).width,[],{height:Math.ceil(font+3),padding:4,grid:true,numbers:380*scale>=220});if(!overlaps(labels))break;}
 host.innerHTML=labels.map(p=>'<text data-shape-name="'+escapeText(p.id)+'" x="'+((p.x+p.width/2)/scale).toFixed(2)+'" y="'+((p.y+p.height/2)/scale).toFixed(2)+'" text-anchor="middle" dominant-baseline="middle" font-size="'+(font/scale).toFixed(2)+'" font-family="system-ui" fill="'+(p.team?'#ffe2b5':'#edf6f0')+'" stroke="#173a30" stroke-width="'+(2/scale).toFixed(2)+'" paint-order="stroke">'+escapeText(p.name)+'</text>').join('');
 host.dataset.labelFont=font;

 host._labels=labels;
}
window.addEventListener('resize',()=>{if(matchPopupActive==='analysis')queueTeamShapeFit();});
document.getElementById('tactics-board').addEventListener('change',event=>{const select=event.target.closest('[data-shape-filter]');if(!select)return;const kind=select.dataset.shapeFilter;previewTacticsDiagram(kind==='owner'?select.value:tacticsDiagramOwner,kind==='zone'?select.value:tacticsDiagramZone,kind);document.querySelector('[data-shape-filter="'+kind+'"]')?.focus({preventScroll:true});});
